use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-column-count176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g1-column-count176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn files(base:&Path,p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir(){files(base,&e.path(),v);}else{assert!(e.file_type().unwrap().is_file());v.push(e.path().strip_prefix(base).unwrap().to_path_buf());}}}
fn main(){let r=Path::new(R);let d=Path::new(D);let dest=r.join("archive-review");assert!(!dest.exists());fs::create_dir(&dest).unwrap();let mut counts=vec![];
for name in["workflow","receipts"]{let at=dest.join(name);fs::create_dir(&at).unwrap();assert!(Command::new("tar").arg("-xzf").arg(d.join(format!("artifacts/{name}.tar.gz"))).arg("-C").arg(&at).status().unwrap().success());let mut all=vec![];files(&at,&at,&mut all);for file in &all{assert_eq!(hash(at.join(file)),hash(r.join(file)));assert!(!file.to_string_lossy().ends_with("-sdk"));assert!(!file.to_string_lossy().ends_with(".words"));}if name=="receipts"{assert_eq!(all.iter().filter(|p|p.file_name().unwrap()=="stdout.log").count(),3);}counts.push(json!({"archive":name,"byte_exact_files":all.len()}));}
for f in["analysis.json","analysis-corrected.json","analysis-segmented.json","review.json","review.log","design.md","correction.md","segmented-design.md"]{assert_eq!(hash(d.join("artifacts").join(f)),hash(r.join(f)));}
let text=fs::read_to_string(d.join("README.md")).unwrap();let mut rest=text.as_str();let mut links=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let end=rest.find(')').unwrap();let link=&rest[..end];if !link.starts_with("https://")&&!link.starts_with('#'){assert!(d.join(link).exists(),"{link}");links+=1;}rest=&rest[end+1..];}
let out=json!({"passed":true,"archives":counts,"local_links_present":links,"raw_scalar_caches_not_published":true,"binaries_not_published":true,"scope":"All archive members and copied raw analyses byte-exact to retained originals. No new models, solves, timings or proofs."});fs::write(d.join("artifacts/archive-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Archive closure PASS;all members byte exact;raw caches/binaries excluded;{links}links");}
